using System;
using System.Collections.Generic;

class Program
{
    // Pretend table: 1,000,000 orders; customer 1 has 900,000 of them, customer 2 has 3.
    static readonly Dictionary<int, int> RowsPerCustomer = new Dictionary<int, int> { { 1, 900000 }, { 2, 3 } };
    static string cachedPlan;   // the plan cache holds ONE plan for this query text

    static string Compile(int sniffedValue)
    {
        // The optimizer chooses based on the estimated rows for the first parameter it sees
        return RowsPerCustomer[sniffedValue] > 50000 ? "Index Scan" : "Index Seek + Key Lookup";
    }

    static long Cost(string plan, int actualRows)
    {
        if (plan == "Index Scan") return 1000000;   // always reads the whole table
        return 4L + actualRows * 3L;                // seek, then 3 reads per matching row
    }

    static void Run(int customerId)
    {
        if (cachedPlan == null) cachedPlan = Compile(customerId);   // compiled once, then reused
        Console.WriteLine("customer " + customerId + " uses '" + cachedPlan + "' cost=" + Cost(cachedPlan, RowsPerCustomer[customerId]));
    }

    static void Main()
    {
        Console.WriteLine("-- first call is the rare customer 2 --");
        Run(2); Run(1);
        cachedPlan = null;                  // recompile, e.g. after a restart
        Console.WriteLine("-- first call is the big customer 1 --");
        Run(1); Run(2);
        // Fixes: OPTION (RECOMPILE), OPTIMIZE FOR, split the query, or Query Store plan forcing.
        // Time O(1) per call, space O(1).
    }
}

using System;
using System.Collections.Generic;

class Program
{
    // Count how often a new key lands in the middle of existing keys (a page split risk)
    // instead of at the end (cheap append).
    static int MiddleInserts(IEnumerable<long> keys)
    {
        var sorted = new List<long>();
        int middle = 0;
        foreach (var k in keys)
        {
            int pos = sorted.BinarySearch(k);          // where would it go in key order?
            if (pos < 0) pos = ~pos;
            if (pos < sorted.Count) middle++;          // not the last slot
            sorted.Insert(pos, k);
        }
        return middle;
    }

    static IEnumerable<long> Identity(int n) { for (long i = 1; i <= n; i++) yield return i; }

    static IEnumerable<long> RandomKeys(int n)
    {
        var r = new Random(7);                         // fixed seed gives repeatable output
        for (int i = 0; i < n; i++) yield return r.NextInt64();
    }

    static void Main()
    {
        int n = 2000;
        Console.WriteLine("inserts: " + n);
        Console.WriteLine("identity (1,2,3...) middle inserts: " + MiddleInserts(Identity(n)));
        Console.WriteLine("random key           middle inserts: " + MiddleInserts(RandomKeys(n)));
        // Sequential keys always append to the last page; random keys hit any page, so pages split.
        // Time O(n log n) searching plus O(n^2) list inserts here; space O(n).
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

class Account
{
    public int Id; public int Balance;
    public Account(int id, int balance) { Id = id; Balance = balance; }
}

class Program
{
    // Always lock the lower Id first. Without this, A->B and B->A can each hold one lock and wait forever.
    static void Transfer(Account from, Account to, int amount)
    {
        Account first = from.Id < to.Id ? from : to;
        Account second = from.Id < to.Id ? to : from;
        lock (first)
        {
            Thread.Sleep(1);                // widen the window where a deadlock would happen
            lock (second)
            {
                from.Balance -= amount;
                to.Balance += amount;
            }
        }
    }

    static void Main()
    {
        var a = new Account(1, 1000);
        var b = new Account(2, 1000);
        Console.WriteLine("before: A=" + a.Balance + " B=" + b.Balance);
        var t1 = Task.Run(() => { for (int i = 0; i < 100; i++) Transfer(a, b, 10); });
        var t2 = Task.Run(() => { for (int i = 0; i < 100; i++) Transfer(b, a, 5); });
        bool done = Task.WaitAll(new[] { t1, t2 }, 10000);
        Console.WriteLine("finished without deadlock: " + done);
        Console.WriteLine("after:  A=" + a.Balance + " B=" + b.Balance + " total=" + (a.Balance + b.Balance));
        // Same idea in SQL: touch tables and rows in the same order in every procedure.
        // Time O(transfers), space O(1).
    }
}

using System;
using System.Collections.Generic;

class Row { public int Id; public string Name; public int Version; }

class Store
{
    readonly Dictionary<int, Row> rows = new Dictionary<int, Row>();
    public Store() { rows[1] = new Row { Id = 1, Name = "Widget", Version = 1 }; }

    public Row Load(int id) { var r = rows[id]; return new Row { Id = r.Id, Name = r.Name, Version = r.Version }; }

    // Equivalent of: UPDATE ... SET Name=@n, Version=Version+1 WHERE Id=@id AND Version=@expected
    public bool Update(int id, string newName, int expectedVersion)
    {
        var r = rows[id];
        if (r.Version != expectedVersion) return false;   // someone else saved first: 0 rows affected
        r.Name = newName;
        r.Version++;
        return true;
    }
}

class Program
{
    static void Main()
    {
        var store = new Store();
        var alice = store.Load(1);     // both users open the same row at version 1
        var bob = store.Load(1);
        Console.WriteLine("Alice and Bob both loaded '" + alice.Name + "' v" + alice.Version);
        Console.WriteLine("Alice saves: " + store.Update(1, "Widget Pro", alice.Version));
        Console.WriteLine("Bob saves:   " + store.Update(1, "Widget Max", bob.Version) + " (conflict)");
        var fresh = store.Load(1);     // Bob reloads, sees Alice's change, and decides what to do
        Console.WriteLine("Bob reloads: '" + fresh.Name + "' v" + fresh.Version);
        Console.WriteLine("Bob retries: " + store.Update(1, "Widget Max", fresh.Version));
        // No locks held while the users think. Time O(1), space O(rows).
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class OutboxMessage { public int Id; public string Payload; public bool Sent; }

class Program
{
    static List<string> orders = new List<string>();            // "Orders table"
    static List<OutboxMessage> outbox = new List<OutboxMessage>(); // "Outbox table", same database
    static HashSet<int> inventoryProcessed = new HashSet<int>();   // consumer's idempotency record

    // Both writes happen in ONE local transaction: either both exist or neither does
    static void PlaceOrder(string name)
    {
        orders.Add(name);
        outbox.Add(new OutboxMessage { Id = outbox.Count + 1, Payload = "OrderPlaced:" + name });
    }

    static void Deliver(OutboxMessage m)       // the Inventory service; may see duplicates
    {
        if (!inventoryProcessed.Add(m.Id)) { Console.WriteLine("  duplicate " + m.Id + " ignored"); return; }
        Console.WriteLine("  inventory reserved stock for " + m.Payload);
    }

    static void Poll(bool crashAfterSend)
    {
        foreach (var m in outbox.Where(x => !x.Sent).ToList())
        {
            Deliver(m);                          // at-least-once delivery
            if (crashAfterSend) { Console.WriteLine("  worker crashed before marking sent"); return; }
            m.Sent = true;
        }
    }

    static void Main()
    {
        PlaceOrder("order-1001");
        PlaceOrder("order-1002");
        Console.WriteLine("orders=" + orders.Count + " outbox=" + outbox.Count);
        Console.WriteLine("poll 1 (worker crashes):"); Poll(true);
        Console.WriteLine("poll 2 (retry):"); Poll(false);
        Console.WriteLine("unsent left: " + outbox.Count(x => !x.Sent));
        // No message is lost, duplicates are harmless. Time O(messages) per poll, space O(messages).
    }
}

using System;
using System.Collections.Generic;

enum State { Detached, Unchanged, Added, Modified, Deleted }

class Customer { public int Id; public string Name; public string City; }

class Tracker
{
    class Entry { public Customer Entity; public string OrigName, OrigCity; public State State; }
    readonly List<Entry> entries = new List<Entry>();

    public void Attach(Customer c) { entries.Add(new Entry { Entity = c, OrigName = c.Name, OrigCity = c.City, State = State.Unchanged }); }
    public void Add(Customer c) { entries.Add(new Entry { Entity = c, State = State.Added }); }
    public void Remove(Customer c) { entries.Find(e => e.Entity == c).State = State.Deleted; }

    // Like DetectChanges(): compare each loaded entity with its copy of the original values
    public void DetectChanges()
    {
        foreach (var e in entries)
            if (e.State == State.Unchanged && (e.Entity.Name != e.OrigName || e.Entity.City != e.OrigCity))
                e.State = State.Modified;
    }

    public void SaveChanges()
    {
        DetectChanges();
        foreach (var e in entries)
            Console.WriteLine("  " + e.State + " -> " + e.Entity.Name);
    }
}

class Program
{
    static void Main()
    {
        var a = new Customer { Id = 1, Name = "Ann", City = "Leeds" };
        var b = new Customer { Id = 2, Name = "Bob", City = "York" };
        var c = new Customer { Id = 3, Name = "Cy", City = "Hull" };
        var t = new Tracker();
        t.Attach(a); t.Attach(b); t.Attach(c);   // as if loaded by a query
        a.City = "Bath";                          // just change a property: no explicit Update call
        t.Remove(c);
        t.Add(new Customer { Id = 4, Name = "Di", City = "Ely" });
        Console.WriteLine("SaveChanges would send:"); t.SaveChanges();
        // Time O(tracked entities) per SaveChanges, space O(tracked entities).
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Order { public int Id; public int CustomerId; }
class Customer { public int Id; public string Name; }

class FakeDb
{
    public int QueryCount;                       // counts "round trips"
    List<Order> orders = Enumerable.Range(1, 5).Select(i => new Order { Id = i, CustomerId = i % 3 + 1 }).ToList();
    List<Customer> customers = new List<Customer>
        { new Customer { Id = 1, Name = "Ann" }, new Customer { Id = 2, Name = "Bob" }, new Customer { Id = 3, Name = "Cy" } };

    public List<Order> GetOrders() { QueryCount++; return orders; }
    public Customer GetCustomer(int id) { QueryCount++; return customers.First(c => c.Id == id); }
    public List<Customer> GetCustomers(IEnumerable<int> ids) { QueryCount++; return customers.Where(c => ids.Contains(c.Id)).ToList(); }
}

class Program
{
    static void Main()
    {
        var db = new FakeDb();
        // N+1: one query for the orders, then one more per order
        foreach (var o in db.GetOrders())
            Console.WriteLine("order " + o.Id + " -> " + db.GetCustomer(o.CustomerId).Name);
        Console.WriteLine("N+1 queries: " + db.QueryCount);

        db = new FakeDb();
        // Fix: load all needed customers in ONE query (what Include or a join does), then look them up in memory
        var orders = db.GetOrders();
        var byId = db.GetCustomers(orders.Select(o => o.CustomerId).Distinct()).ToDictionary(c => c.Id);
        foreach (var o in orders)
            Console.WriteLine("order " + o.Id + " -> " + byId[o.CustomerId].Name);
        Console.WriteLine("batched queries: " + db.QueryCount);
        // N+1 costs 1+N round trips; the fix costs 2. Space O(N) for the lookup.
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static int rowsRead;                          // how many rows left the "database"

    static IEnumerable<int> Table()               // stands in for a table with 1,000 rows
    {
        for (int i = 1; i <= 1000; i++) { rowsRead++; yield return i; }
    }

    static void Main()
    {
        // Filter first, then run: only the matching rows are produced (like Where then ToList on IQueryable)
        rowsRead = 0;
        var query = Table().Where(x => x % 250 == 0).Take(2);    // nothing has run yet: deferred
        Console.WriteLine("after building the query, rows read: " + rowsRead);
        var result = query.ToList();                              // runs now, stops after 2 matches
        Console.WriteLine("result: [" + string.Join(", ", result) + "] rows read: " + rowsRead);

        // ToList too early: every row is materialized, then filtered in memory (ToList before Where)
        rowsRead = 0;
        var all = Table().ToList();                               // pulls all 1,000 rows
        var filtered = all.Where(x => x % 250 == 0).Take(2).ToList();
        Console.WriteLine("early ToList result: [" + string.Join(", ", filtered) + "] rows read: " + rowsRead);
        // With EF Core the first form sends WHERE and TOP to SQL, the second transfers the whole table.
        // Time O(rows read), space O(1) versus O(n).
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Order { public string Id; public string Country; public string CustomerId; }

class Program
{
    // Stand-in for hashing a partition key value to one of N physical partitions
    static int Partition(string key, int count)
    {
        int h = 17;
        foreach (char c in key) h = h * 31 + c;     // simple repeatable hash
        return Math.Abs(h % count);
    }

    static void Report(string name, IEnumerable<Order> orders, Func<Order, string> keySelector, int partitions)
    {
        var counts = new int[partitions];
        foreach (var o in orders) counts[Partition(keySelector(o), partitions)]++;
        Console.WriteLine(name.PadRight(22) + " items per partition: " + string.Join(", ", counts)
            + "  (max share " + (100 * counts.Max() / orders.Count()) + "%)");
    }

    static void Main()
    {
        var orders = new List<Order>();
        for (int i = 0; i < 1000; i++)
            orders.Add(new Order { Id = "o" + i, Country = i % 10 < 8 ? "GB" : "FR", CustomerId = "c" + (i % 200) });
        // Low-cardinality key: 80% of the data lands on one value, so one partition runs hot
        Report("key = Country", orders, o => o.Country, 4);
        // High-cardinality key that queries filter on: even spread
        Report("key = CustomerId", orders, o => o.CustomerId, 4);
        // Good keys have many distinct values, even load, and appear in the common query filter.
        // Time O(n), space O(partitions).
    }
}

using System;
using System.Collections.Generic;

class ThrottledException : Exception
{
    public int RetryAfterMs;
    public ThrottledException(int ms) { RetryAfterMs = ms; }
}

class Program
{
    static int budget = 3;                        // pretend the container only allows 3 requests per window

    static string Call(int n)
    {
        if (budget == 0) { budget = 2; throw new ThrottledException(100); }   // 429 with a retry-after hint
        budget--;
        return "ok-" + n;
    }

    static string WithRetry(int n, int maxAttempts, List<string> log)
    {
        int delay = 0;
        for (int attempt = 1; ; attempt++)
        {
            try { return Call(n); }
            catch (ThrottledException e)
            {
                if (attempt == maxAttempts) throw;                       // give up, surface the error
                delay = Math.Max(e.RetryAfterMs, delay * 2);             // obey the server hint, back off further
                log.Add("request " + n + " throttled, waiting " + delay + " ms");
                // A real client would sleep here: await Task.Delay(delay)
            }
        }
    }

    static void Main()
    {
        var log = new List<string>();
        for (int i = 1; i <= 8; i++) Console.WriteLine(WithRetry(i, 5, log));
        Console.WriteLine("retries: " + log.Count);
        foreach (var l in log) Console.WriteLine("  " + l);
        // Retrying hides symptoms; the real fix is fewer RUs per request or more throughput.
        // Time O(requests x attempts), space O(log).
    }
}

using System;
using System.Collections.Generic;

class Event { public string OrderId; public int Version; public string Status; }
class ReadDoc { public string OrderId; public int Version; public string Status; }

class Program
{
    static Dictionary<string, ReadDoc> readStore = new Dictionary<string, ReadDoc>();   // stands in for Cosmos DB

    // Idempotent and order-safe: an older or duplicate event never overwrites a newer state
    static void Apply(Event e)
    {
        ReadDoc doc;
        if (readStore.TryGetValue(e.OrderId, out doc) && doc.Version >= e.Version)
        {
            Console.WriteLine("  skip   v" + e.Version + " " + e.Status + " (have v" + doc.Version + ")");
            return;
        }
        readStore[e.OrderId] = new ReadDoc { OrderId = e.OrderId, Version = e.Version, Status = e.Status };
        Console.WriteLine("  apply  v" + e.Version + " " + e.Status);
    }

    static void Main()
    {
        // The messages arrive shuffled and one is duplicated
        var arrivals = new List<Event>
        {
            new Event { OrderId = "A1", Version = 1, Status = "Created" },
            new Event { OrderId = "A1", Version = 3, Status = "Shipped" },
            new Event { OrderId = "A1", Version = 2, Status = "Paid" },        // late
            new Event { OrderId = "A1", Version = 3, Status = "Shipped" },     // duplicate
        };
        foreach (var e in arrivals) Apply(e);
        Console.WriteLine("final: v" + readStore["A1"].Version + " " + readStore["A1"].Status);
        // The version comes from the source row (rowversion or a counter). Time O(1) per event, space O(orders).
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static Dictionary<int, KeyValuePair<string, int>> cache = new Dictionary<int, KeyValuePair<string, int>>(); // value + expiry tick
    static int now = 0;            // fake clock so the output is repeatable
    static int dbReads = 0;

    static string LoadFromDb(int id) { dbReads++; return "product-" + id; }

    static string Get(int id)
    {
        KeyValuePair<string, int> hit;
        if (cache.TryGetValue(id, out hit) && hit.Value > now)    // 1. look in the cache first
        {
            Console.WriteLine("t=" + now + " id=" + id + " HIT");
            return hit.Key;
        }
        string value = LoadFromDb(id);                            // 2. miss: go to the database
        cache[id] = new KeyValuePair<string, int>(value, now + 10);   // 3. store it with a 10 tick TTL
        Console.WriteLine("t=" + now + " id=" + id + " MISS -> loaded");
        return value;
    }

    static void Update(int id)
    {
        cache.Remove(id);                                         // on write, delete the key (do not update it)
        Console.WriteLine("t=" + now + " id=" + id + " updated, cache entry removed");
    }

    static void Main()
    {
        Get(1); now = 3; Get(1); Get(2);
        now = 5; Update(1); Get(1);
        now = 20; Get(1);                                         // the entry expired
        Console.WriteLine("database reads: " + dbReads + " for 6 requests");
        // Cache lookup is O(1); the database is touched only on a miss. Space O(cached items).
    }
}

using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static int dbCalls;
    static readonly Dictionary<string, Lazy<Task<string>>> inFlight = new Dictionary<string, Lazy<Task<string>>>();

    static async Task<string> SlowLoad(string key)
    {
        Interlocked.Increment(ref dbCalls);        // count real database hits
        await Task.Delay(100);                     // pretend the query takes 100 ms
        return "value-of-" + key;
    }

    // All callers for the same key share ONE task; only the first one starts the load
    static Task<string> GetSingleFlight(string key)
    {
        Lazy<Task<string>> lazy;
        lock (inFlight)
        {
            if (!inFlight.TryGetValue(key, out lazy))
            {
                lazy = new Lazy<Task<string>>(() => SlowLoad(key));
                inFlight[key] = lazy;
            }
        }
        return lazy.Value;
    }

    static async Task Main()
    {
        var naive = new List<Task<string>>();
        for (int i = 0; i < 50; i++) naive.Add(SlowLoad("hot"));          // 50 users all miss at once
        await Task.WhenAll(naive);
        Console.WriteLine("without protection: database calls = " + dbCalls);

        dbCalls = 0;
        var shared = new List<Task<string>>();
        for (int i = 0; i < 50; i++) shared.Add(GetSingleFlight("hot"));
        var results = await Task.WhenAll(shared);
        Console.WriteLine("with single flight:  database calls = " + dbCalls + ", all got '" + results[0] + "'");
        // 50 concurrent misses become 1 load. Time O(1) per caller, space O(keys being loaded).
    }
}

using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

class Pool
{
    readonly SemaphoreSlim slots;
    public Pool(int size) { slots = new SemaphoreSlim(size, size); }
    public bool TryOpen(int timeoutMs) { return slots.Wait(timeoutMs); }   // timeout means "pool exhausted"
    public void Release() { slots.Release(); }                            // like Dispose / Close returning it
}

class Program
{
    static void Main()
    {
        var pool = new Pool(3);                      // max pool size 3 for the demo (the default is 100)
        Console.WriteLine("leaky code: opens a connection and never returns it");
        for (int i = 1; i <= 5; i++)
            Console.WriteLine("  request " + i + (pool.TryOpen(50) ? " got a connection" : " TIMEOUT: pool exhausted"));

        pool = new Pool(3);
        Console.WriteLine("correct code: using/finally returns it every time");
        for (int i = 1; i <= 5; i++)
        {
            bool ok = pool.TryOpen(50);
            try { Console.WriteLine("  request " + i + (ok ? " got a connection" : " TIMEOUT")); }
            finally { if (ok) pool.Release(); }      // always release, even on an exception
        }
        // In .NET: await using var conn = new SqlConnection(cs); keeps the scope short.
        // Each acquire is O(1); the pool holds at most max-size physical connections.
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static int Hash(string s)
    {
        unchecked { int h = 23; foreach (char c in s) h = h * 31 + c; h ^= (h >> 13); h *= 0x5bd1e995; h ^= (h >> 15); return h & 0x7fffffff; }
    }

    // Ring: each shard gets 50 points; a key belongs to the first point clockwise from its hash
    static SortedDictionary<int, string> BuildRing(IEnumerable<string> shards)
    {
        var ring = new SortedDictionary<int, string>();
        foreach (var s in shards)
            for (int v = 0; v < 50; v++) ring[Hash(s + "#" + v)] = s;
        return ring;
    }

    static string Lookup(SortedDictionary<int, string> ring, string key)
    {
        int h = Hash(key);
        foreach (var p in ring) if (p.Key >= h) return p.Value;
        return ring.First().Value;                   // wrap around the ring
    }

    static void Main()
    {
        var keys = Enumerable.Range(1, 1000).Select(i => "tenant-" + i).ToList();
        var before = BuildRing(new[] { "shard1", "shard2", "shard3" });
        var after = BuildRing(new[] { "shard1", "shard2", "shard3", "shard4" });

        int movedRing = keys.Count(k => Lookup(before, k) != Lookup(after, k));
        int movedMod = keys.Count(k => Hash(k) % 3 != Hash(k) % 4);   // naive hash % shardCount
        Console.WriteLine("keys: " + keys.Count + ", shards 3 -> 4");
        Console.WriteLine("moved with consistent hashing: " + movedRing + " (about 1/4 expected)");
        Console.WriteLine("moved with hash % N:           " + movedMod + " (most keys move)");
        // Lookup is O(ring size) here (O(log n) with a sorted array and binary search). Space O(shards x points).
    }
}
